head.script:
(function () {
  const XHTML_NS = 'http://www.w3.org/1999/xhtml';
  const root = document.querySelector('foreignObject').firstElementChild;
  const createElementNS = document.createElementNS.bind(document);
  Object.defineProperty(document, 'head', { get: () => root.querySelector('head'), configurable: true });
  Object.defineProperty(document, 'body', { get: () => root.querySelector('body'), configurable: true });
  Object.defineProperty(document, 'documentElement', { get: () => root, configurable: true });
  document.createElement = function (tagName, options) { return createElementNS(XHTML_NS, tagName, options); };
})();

body.script:
let scramjet, frame, transport;
let wispUrl = localStorage.getItem('wispUrl') || 'wss://wisp.mercurywork.shop/';
document.getElementById('wispInput').value = wispUrl;

function showStatus(msg, err=false){
  const s=document.getElementById('status');
  s.style.display='flex';
  s.className = err ? 'max-w-2xl mx-auto mt-4 flex items-center gap-2 px-4 py-2 rounded-xl bg-red-500/10 border border-red-500/20 text-red-300 text-xs' : 'max-w-2xl mx-auto mt-4 flex items-center gap-2 px-4 py-2 rounded-xl bg-amber-500/10 border border-amber-500/20 text-amber-300 text-xs';
  document.getElementById('statusText').textContent = msg;
}

function resolveUrl(input){
  input=input.trim();
  if(!input) return null;
  if(input.includes('.') && !input.includes(' ') && !input.startsWith('http')){
    // looks like domain
    if(input.includes('://')) return input;
    return 'https://' + input;
  }
  if(input.startsWith('http://') || input.startsWith('https://')) return input;
  // search
  return 'https://duckduckgo.com/?q=' + encodeURIComponent(input);
}

async function ensureInit(){
  if(scramjet && frame) return true;
  showStatus('Initializing Scramjet...');
  try{
    await navigator.serviceWorker.ready;
    const serviceworker = navigator.serviceWorker.controller || (await navigator.serviceWorker.ready).active;
    if(!serviceworker){ showStatus('No service worker - need HTTPS', true); return false; }
    const { Controller } = $scramjetController;
    const { defaultConfig } = $scramjet;
    const EpoxyTransport = self.EpoxyTransport.default;
    transport = new EpoxyTransport({ wisp: wispUrl });
    await transport.init();
    scramjet = new Controller({ serviceworker, transport, scramjetConfig: defaultConfig });
    await scramjet.wait();
    frame = scramjet.createFrame(document.getElementById('browserFrame'));
    // keep url bar synced if scramjet emits
    try{ frame.addEventListener('urlchange', e=>{ document.getElementById('urlBar').value = e.url || ''; }); }catch{}
    document.getElementById('status').style.display='none';
    return true;
  }catch(e){
    console.error(e);
    showStatus(e.message || 'Failed to init - check WISP online', true);
    return false;
  }
}

async function navigate(url){
  url = resolveUrl(url);
  if(!url) return;
  document.getElementById('loader').style.display='flex';
  document.getElementById('browserView').classList.add('active');
  document.getElementById('urlBar').value = url;
  const ok = await ensureInit();
  if(!ok){ document.getElementById('loader').style.display='none'; return; }
  frame.go(url);
  setTimeout(()=>{ document.getElementById('loader').style.display='none'; }, 900);
}

function doSearch(){ navigate(document.getElementById('mainSearch').value); }
function goQuick(url){ navigate(url); }

document.getElementById('mainSearch').addEventListener('keydown', e=>{ if(e.key==='Enter') doSearch(); });
document.getElementById('urlBar').addEventListener('keydown', e=>{ if(e.key==='Enter') navigate(e.target.value); });

function closeBrowser(){ document.getElementById('browserView').classList.remove('active'); }
function navBack(){ try{ frame.back(); }catch{} }
function navForward(){ try{ frame.forward(); }catch{} }
function navReload(){ try{ frame.reload(); }catch{} }
function toggleFullscreen(){ const f=document.getElementById('browserFrame'); if(document.fullscreenElement) document.exitFullscreen(); else f.requestFullscreen?.(); }
function toggleSettings(){ const el=document.getElementById('settings'); el.style.display = el.style.display==='flex' ? 'none' : 'flex'; if(el.style.display==='flex') el.classList.add('flex'); }
function saveSettings(){ localStorage.setItem('wispUrl', document.getElementById('wispInput').value.trim()); location.reload(); }
function cloak(){
  const url = location.href;
  const w = window.open('about:blank','_blank');
  if(!w) return alert('Allow popups for cloaking');
  w.document.title='Home | Infinite Campus';
  w.document.body.style.cssText='margin:0;height:100vh';
  const f=w.document.createElement('iframe');
  f.style.cssText='width:100%;height:100%;border:0'; f.src=url; w.document.body.appendChild(f);
  location.replace('https://classroom.google.com');
}

// register SW
if('serviceWorker' in navigator){
  navigator.serviceWorker.register('./sw.js').then(()=>console.log('sw registered')).catch(e=>showStatus('SW fail: '+e.message, true));
} else {
  showStatus('Service workers not supported - need HTTPS', true);
}
